      "question": "How does calcium carbide ripen mangoes?",
      "options": [
        "It reacts with moisture and releases Ethylene",
        "It reacts with moisture and releases Acetaldehyde, which in turn releases ethylene",
        "It reacts with starch and releases Acetylene",
        "It reacts with moisture and releases Ethyne"
      ],
      "correct": 0,
      "explanation": "It reacts with moisture and releases Ethylene]- or reasons of safe  transportation of fruits, mangoes, bananas etc are picked before they ripen fully. Slightly green  harvested mangoes are subjected to small containers of calcium carbide (CaC2) with a plastic  covering. CaC2 reacts with the moisture in the air to release acetylene (or ethyne) gas as  follows:  CaC2 + 2 H2O \u2192 C2H2 + Ca(OH)2  This option may give you slightest confusion if you don\u2018t know the difference between Ethylene  and Ethyne (Acetylene). Both are chemical substances produced by fruits to accelerate the  normal process of fruit maturation \u2014 is a ripening hormone. Ethylene is C2H4 and has a  carbon-carbon double bond. Acetylene is C2H2 and has a carbon-carbon triple bind. Acetylene  contains more energy and burns hotter than ethylene. Ethylene is a gaseous compound ,  Acetylene is the chemical compound , which is the simplest alkyne and is also a hydrocarbon  while Ethylene is the simplest alkene and classified as an unsaturated hydrocarbon. I hope you  will never forget it now.       MCQs                                                                             GENERAL SCIENCE                                                                     MCQs  120 | P a g e",
